import os, re, json

def load_demo():
    env_dir = os.environ.get('RLM_SESSION_DIR')
    if not env_dir:
        return {}
    session_file = os.path.join(env_dir, '../../sessions', os.path.basename(env_dir) + '.jsonl')
    try:
        t = open(session_file).read()
    except:
        return {}

    demos = {}
    pattern = re.compile(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', re.MULTILINE)

    text_before = None
    for m in pattern.finditer(t):
        full = m.group(0)
        lines = full.replace('\\n', '\n').split('\n')[:m.group(1)].split('\n')
        demos[m.group(1)] = [int(x) for x in lines[0].split()]
        demos[m.group(1)+'_rows'] = [int(x) for x in lines[1].split()]

    return {
        'Task ID': pattern.sub('', []).split()[0] if pattern else 'unknown',
    }

G = load_demo()
print("Loaded demos:", G)
