def transform(grid):
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    min_6_r = min(r for r in range(h) if any(grid[r][c] == 6 for c in range(w)))
    max_6_r = max(r for r in range(h) if any(grid[r][c] == 6 for c in range(w)))

    # Remove all 6s
    for r in range(min_6_r, max_6_r + 1):
        for c in range(w):
            if grid[r][c] == 6:
                result[r][c] = 0

    # Get 4s rows above min_6_r
    four_rows = [r for r in range(min_6_r) if any(grid[r][c] == 4 for c in range(w))]

    # Ensure enough rows (pad if needed)
    needed = max_6_r - min_6_r + 1
    while len(four_rows) < needed:
        pad_row = min_6_r - len(four_rows) - 1
        if pad_row >= 0:
            four_rows.insert(0, pad_row)

    # Sort descending and copy
    four_rows.sort(reverse=True)

    for i, src_row in enumerate(four_rows[:needed]):
        dst_row = min_6_r + i
        for src_col in range(w):
            if grid[src_row][src_col] == 4:
                result[dst_row][src_col] = 4

    return result

